const SYSTEM = "Voc\u00ea escreve para o Instagram profissional da Anna, m\u00e9dica-veterin\u00e1ria que atende em DOMIC\u00cdLIO c\u00e3es e gatos, com \u00eanfase em medicina felina (ela \u00e9 p\u00f3s-graduada em medicina felina). Escreva em portugu\u00eas do Brasil, na primeira pessoa do singular, como se fosse a pr\u00f3pria Anna. Tom: acolhedor, claro, pr\u00f3ximo e respons\u00e1vel, para tutores leigos. No m\u00e1ximo 2 emojis. Regras: nunca diagnostique nem prescreva; nunca indique medicamentos ou doses (v\u00e1rios rem\u00e9dios humanos s\u00e3o perigosos para gatos e c\u00e3es); n\u00e3o prometa cura; n\u00e3o cite pre\u00e7os, promo\u00e7\u00f5es nem regi\u00e3o atendida; n\u00e3o critique outros profissionais. O atendimento domiciliar n\u00e3o substitui hospital: em sinais de emerg\u00eancia (dificuldade para respirar, tentativas de urinar sem sucesso, convuls\u00e3o, sangramento, v\u00f4mitos repetidos, apatia intensa, suspeita de intoxica\u00e7\u00e3o, trauma), oriente procurar pronto atendimento veterin\u00e1rio imediatamente. Quando fizer sentido, e sem exagero, mencione as vantagens do atendimento em casa (menos estresse, ambiente conhecido). Termine com um convite suave para agendar um atendimento pelo WhatsApp ou direct. Responda SOMENTE com um objeto JSON v\u00e1lido, sem texto fora dele, com as chaves: \"legenda\" (legenda completa com 5 a 8 hashtags no final), \"roteiro\" (se formato=reels: roteiro falado de 30 a 45 segundos com cenas; se carrossel: texto de 6 a 8 slides, um por linha, come\u00e7ando por 'Slide 1:'; se imagem: texto curto para a arte), \"sugestao_visual\" (descri\u00e7\u00e3o da imagem ou do v\u00eddeo a produzir).";
const temas = ["Bolas de pelo em gatos: quando \u00e9 normal e quando \u00e9 sinal de alerta", "Como \u00e9 uma consulta veterin\u00e1ria em domic\u00edlio, passo a passo", "Meu gato bebe pouca \u00e1gua: como estimular a hidrata\u00e7\u00e3o", "Vacina\u00e7\u00e3o e vermifuga\u00e7\u00e3o de filhotes de c\u00e3es: o que saber", "Doen\u00e7a renal cr\u00f4nica em gatos: sinais precoces", "Por que tantos gatos sofrem com a ida ao veterin\u00e1rio (e como o atendimento em casa ajuda)", "Castra\u00e7\u00e3o de gatos: benef\u00edcios e mitos", "Alimentos t\u00f3xicos para c\u00e3es: chocolate, uva, cebola e outros", "Vacinas essenciais para gatos (V4/V5 e FeLV): quando fazer", "Estresse felino e enriquecimento ambiental dentro de casa", "Check-up anual: por que levar o c\u00e3o ao veterin\u00e1rio mesmo saud\u00e1vel", "Obstru\u00e7\u00e3o urin\u00e1ria em gatos: por que \u00e9 uma emerg\u00eancia", "Casa com v\u00e1rios pets: vantagens do atendimento domiciliar", "Cuidados com gatos idosos: o que muda depois dos 10 anos", "Pulgas e carrapatos em c\u00e3es e gatos: preven\u00e7\u00e3o segura", "Sa\u00fade bucal em gatos: gengivite e doen\u00e7a periodontal", "Plantas t\u00f3xicas para gatos, como o l\u00edrio: o que evitar em casa", "Calor e hipertermia em c\u00e3es: sinais e preven\u00e7\u00e3o", "O que o xixi e as fezes do seu gato contam sobre a sa\u00fade dele", "Gatos escondem a dor: sinais sutis que o tutor precisa notar", "Pets idosos ou com mobilidade reduzida: por que o atendimento em casa faz diferen\u00e7a", "Mitos e verdades sobre gatos", "Como preparar o gato para a consulta e usar a caixa de transporte sem estresse", "Chegada de um filhote (gato ou c\u00e3o): primeiros cuidados e primeira consulta", "Obesidade em gatos e c\u00e3es: como perceber e por que importa"];

const formatos = ['carrossel', 'reels', 'imagem'];
const sd = $getWorkflowStaticData('global');
const i = sd.i || 0;
const out = [];
for (let k = 0; k < 3; k++) {
  const tema = temas[(i + k) % temas.length];
  const formato = formatos[k % formatos.length];
  const body = {
    model: "claude-sonnet-5-5",
    max_tokens: 1500,
    system: SYSTEM,
    messages: [{ role: 'user', content: `Tema: ${tema}\nFormato: ${formato}\nCrie o conteúdo.` }]
  };
  out.push({ json: { tema, formato, body } });
}
sd.i = (i + 3) % temas.length;
return out;

const items = $input.all();
const out = [];
items.forEach((it, i) => {
  const ctx = $('Escolher temas').all()[i].json;
  let d;
  try {
    const t = it.json.content[0].text;
    d = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
  } catch (e) {
    d = { legenda: '(erro ao interpretar a resposta da IA - gere novamente)', roteiro: '', sugestao_visual: '' };
  }
  out.push({ json: {
    codigo: Date.now() + '-' + i,
    data_criacao: new Date().toISOString(),
    tema: ctx.tema,
    formato: ctx.formato,
    legenda: d.legenda || '',
    roteiro: typeof d.roteiro === 'string' ? d.roteiro : JSON.stringify(d.roteiro || ''),
    sugestao_visual: d.sugestao_visual || '',
    image_url: '',
    status: 'rascunho',
    publicado_em: ''
  }});
});
return out;
